import { beforeEach, describe, expect, it } from 'vitest';

// Story 24-S6 — the library's Create filters count every puzzle the caller
// can edit: their own and those shared with them (`shared`, set by the
// library page for puzzles the caller collaborates on). Play and Size are
// unchanged. A puzzle without `shared` is judged as before (18-S4).
//
// The module is loaded through a variable path, with its types declared
// here, so the specification-only baseline type-checks; missing runtime
// stays red. Do not edit this file to match an implementation.

type PlayState = 'untouched' | 'in-progress' | 'completed';
interface Puzzle {
  id: string;
  builderId: string;
  shared?: boolean;
  phase: 'grid' | 'hints';
  publishedAt: string | null;
  visibility: 'private' | 'public';
  cols: number;
  rows: number;
  play: { state: PlayState; sessionId: string | null } | null;
}
interface Filters {
  play: ('unplayed' | 'underway' | 'complete')[];
  create: ('build' | 'hint' | 'unlisted')[];
  size: ('mini' | 'midi' | 'daily' | 'sunday')[];
}

let filterPuzzles: (puzzles: readonly Puzzle[], filters: Filters, userId: string) => Puzzle[];

beforeEach(async () => {
  const modulePath = './puzzle-filters';
  const implementation = await import(modulePath) as Record<string, unknown>;
  expect(typeof implementation.filterPuzzles).toBe('function');
  filterPuzzles = implementation.filterPuzzles as typeof filterPuzzles;
});

const ME = 'me';
const OWNER = 'owner';

function puzzle(id: string, builderId: string, kind: 'grid' | 'hints' | 'unlisted' | 'public', shared?: boolean, state: PlayState = 'untouched'): Puzzle {
  const published = kind === 'unlisted' || kind === 'public';
  return {
    id,
    builderId,
    ...(shared === undefined ? {} : { shared }),
    phase: kind === 'grid' ? 'grid' : 'hints',
    publishedAt: published ? '2026-10-01T00:00:00.000Z' : null,
    visibility: kind === 'public' ? 'public' : 'private',
    cols: 5,
    rows: 5,
    play: published ? { state, sessionId: state === 'untouched' ? null : `s-${id}` } : null,
  };
}

const LIBRARY: Puzzle[] = [
  puzzle('own-grid', ME, 'grid', false),
  puzzle('shared-grid', OWNER, 'grid', true),
  puzzle('shared-hints', OWNER, 'hints', true),
  puzzle('shared-unlisted', OWNER, 'unlisted', true),
  puzzle('shared-public-underway', OWNER, 'public', true, 'in-progress'),
  puzzle('foreign-grid', OWNER, 'grid', false),
  puzzle('foreign-unlisted', OWNER, 'unlisted', false, 'in-progress'),
  puzzle('legacy-own-hints', ME, 'hints'),
  puzzle('legacy-foreign-hints', OWNER, 'hints'),
];

const filters = (partial: Partial<Filters>): Filters => ({ play: [], create: [], size: [], ...partial });
const ids = (partial: Partial<Filters>) => filterPuzzles(LIBRARY, filters(partial), ME).map((p) => p.id);

describe('24-S6-3 Create filters count editable puzzles', () => {
  it('a shared puzzle counts for Build Phase, Hint Phase and Unlisted as an own one does', () => {
    expect(ids({ create: ['build'] })).toEqual(['own-grid', 'shared-grid']);
    expect(ids({ create: ['hint'] })).toEqual(['shared-hints', 'legacy-own-hints']);
    expect(ids({ create: ['unlisted'] })).toEqual(['shared-unlisted']);
  });

  it('another builder’s unshared puzzle never counts', () => {
    const all = ids({ create: ['build', 'hint', 'unlisted'] });
    expect(all).not.toContain('foreign-grid');
    expect(all).not.toContain('foreign-unlisted');
    expect(all).not.toContain('legacy-foreign-hints');
  });

  it('Play filters treat shared puzzles as any other', () => {
    expect(ids({ play: ['underway'] })).toEqual(['shared-public-underway', 'foreign-unlisted']);
    expect(ids({ play: ['unplayed'] })).toEqual(['shared-unlisted']);
  });
});
